-- Client onboarding deck (3 Sep 2026) — template rebuild + yes/no step type +
-- Daniel's event activation. Marcus/Daniel/the owner rulings from the 2 Sep call.
--
-- What this does:
--   1. Adds step_type 'yes_no' (question → Yes uploads/lists, No completes).
--   2. Rebuilds client_flow_stages/steps as the 12-card deck: login, the
--      38-question onboarding form (verbatim from Jotform 260183612532046,
--      minus the five upload/list questions that became their own cards and
--      the "type YES" question), team@ mailbox, 60-min booking, calendar,
--      then one card each for pitch deck, priority companies, re-engagement,
--      do-not-contact, fee plans, anything else. Best-practice guide kept but
--      disabled (the owner, 3 Sep). No "campaign live" stage: the client presses
--      "Take me to my dashboard" themselves.
--   3. Activates Daniel's onboarding event at 60 minutes (availability rules
--      untouched — his own).
--   4. Puts a 25 MB size limit on the client-onboarding-assets bucket.
--
-- SAFE TO RUN: journeys are snapshots, so this only shapes NEW journeys. The
-- rebuild aborts if any non-test journey exists (none did on 3 Sep).
-- Delete + recreate the "Final Test" test client from Dev Center afterwards.
--
-- NOTE: applied by the owner via the hosted SQL editor; migration bookkeeping
--       unaware. Never `supabase db push`. Repair list:
--       supabase migration repair --status applied 20260903120000

-- 1. step_type CHECK gains 'yes_no'
DO $$
DECLARE c record;
BEGIN
  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid = 'public.client_flow_steps'::regclass AND contype = 'c'
      AND pg_get_constraintdef(oid) ILIKE '%step_type%'
  LOOP
    EXECUTE format('ALTER TABLE public.client_flow_steps DROP CONSTRAINT %I', c.conname);
  END LOOP;
END $$;
ALTER TABLE public.client_flow_steps
  ADD CONSTRAINT client_flow_steps_step_type_check
  CHECK (step_type IN ('confirm','form','booking','calendar_connect','upload','text_list','read_document','link','yes_no'));

-- 2. Template rebuild (guarded)
DO $$
DECLARE
  v_stage uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM public.client_onboarding_journeys WHERE is_test IS NOT TRUE) THEN
    RAISE EXCEPTION 'Real client journeys exist — rebuild refused. Edit the flow in the builder instead.';
  END IF;

  DELETE FROM public.client_flow_steps;
  DELETE FROM public.client_flow_stages;
  INSERT INTO public.client_flow_stages (stage_key, title, subtitle, sort_order, enabled)
  VALUES ('account_setup', 'Welcome', 'Your login is ready', 10, true) RETURNING id INTO v_stage;
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'create_login', 'Create your login', 'Welcome aboard. This first step ticks itself the moment you sign in, so you''re already one down.', 'confirm', $j${"auto": "first_sign_in"}$j$::jsonb, 1, true);
  INSERT INTO public.client_flow_stages (stage_key, title, subtitle, sort_order, enabled)
  VALUES ('onboarding_form', 'About your business', 'The foundation of your whole campaign', 20, true) RETURNING id INTO v_stage;
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'onboarding_form', 'Tell us about your business', 'Next, I need you to complete the onboarding form. It''s the single most important thing you''ll do here: every list we build, every call we make and every message we send starts from these answers. It opens full-screen, saves as you type, and you can come back to it whenever you like.', 'form', $j${"questions": [{"key": "company_name", "label": "Your Company Name", "type": "text", "required": true, "section": "Business Details", "prefill": "company_name"}, {"key": "company_website", "label": "Company Website", "type": "text", "required": true, "section": "Business Details"}, {"key": "your_name", "label": "Your Name", "type": "fullname", "required": true, "section": "Business Details", "prefill": "contact_name"}, {"key": "email", "label": "Your email address", "type": "email", "required": true, "section": "Business Details", "prefill": "email"}, {"key": "mobile", "label": "What is the best mobile number to reach you?", "type": "phone", "required": true, "section": "Business Details"}, {"key": "other_contacts", "label": "Please provide details of anybody else from your company that you would like to be involved in communications/ points of contact for this campaign.", "type": "textarea", "required": true, "section": "Business Details", "help": "If this doesn't apply then please type 'Not Applicable'"}, {"key": "billing_email", "label": "Please provide the email address for your accounts/ billing department", "type": "text", "required": false, "section": "Business Details", "help": "We'll cc this address on invoices alongside your main contact, if this doesn't apply then please type 'Not Applicable'"}, {"key": "office_address", "label": "What is the full address of your business office?", "type": "address", "required": true, "section": "Business Details"}, {"key": "timezone", "label": "Which time zone are you in?", "type": "text", "required": true, "section": "Business Details"}, {"key": "years_running", "label": "How many years has your business been running?", "type": "text", "required": true, "section": "Business Details"}, {"key": "service_types", "label": "Which recruitment services do you provide?", "type": "checkbox", "required": true, "section": "Business Details", "help": "Select all that apply", "options": ["Executive Search", "Permanent", "Temporary", "Contract", "Embedded"]}, {"key": "countries", "label": "Which country/countries does your business operate in?", "type": "checkbox", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "Please select all that apply for this campaign", "options": ["United Kingdom", "Europe", "United States", "Middle East"]}, {"key": "us_states", "label": "If you selected the United States, which States are relevant to this campaign?", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "List specific States or write “Nationwide” if there’s no restriction. If you didn't select the US please write 'Not Applicable'."}, {"key": "industry_or_talent_led", "label": "Would you say you're more industry led or talent led?", "type": "checkbox", "required": true, "section": "Ideal Customer Profile (ICP)", "options": ["Industry led (you place most/all types of candidates within specific industries/sectors that you specialise in)", "Talent led (you place specific types/ levels of candidates across any/ multiple sectors)"]}, {"key": "talent_led_indicators", "label": "If you said more candidate focused then what are some key indicators/ attributes of companies that have a need for the types of candidates that you place?", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "For example if you only place finance professionals then a key indicator of companies that hire finance professionals are one’s that have a CFO because that means they have a finance department"}, {"key": "target_industries", "label": "Please provide all relevant industries that you would like us to target for this campaign", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "Example: “Renewable energy ”, “FMCG”, “Construction\", \"SAAS\""}, {"key": "industry_keywords", "label": "Please let us know the relevant industry keywords we should use in targeting?", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "Which words appear in your ideal client's LinkedIn company description? For example: \"software development\", \"manufacturing\", \"supply chain\", \"B2B sales\""}, {"key": "icp_criteria", "label": "What type of companies are a good fit? In other words, what is your ICP? Include any/all criteria that matters to you.", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "For example e.g. Revenue, Number of employees, Funding Stage, Locations etc). These answers will help guide the lead list building process."}, {"key": "candidate_types", "label": "We want to know about the types of candidates you specialise in placing. Please tell us firstly what are the job titles that you specialise in placing? Secondly what level of role's do you place? Thirdly what is the collective term for these candidates?", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "Please provide roles/ job titles for each industry named along with level (for example, entry level, c suite etc). For collective term we mean if you place accountants, auditors and financial directors then the collective term is 'finance professionals'"}, {"key": "decision_makers", "label": "Who is primarily responsible for making/influencing hiring decisions for each of the roles you mentioned in the previous question?", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "Please include primary (e.g. CEO, Founder, MD etc) and secondary decision makers (e.g. Chief of People, HR Director, CTO, COO)"}, {"key": "example_companies", "label": "Please list 5-10 examples of companies in each market that you target that you would like to work with.", "type": "textarea", "required": true, "section": "Ideal Customer Profile (ICP)", "help": "Please include each company's website URL"}, {"key": "elevator_pitch", "label": "What's your 'Elevator Pitch'?", "type": "textarea", "required": true, "section": "Business Development", "help": "If you had 30 seconds to explain what you do to a potential client, what would you say? Focus on who you help, the problem you solve, and the outcome you deliver. Include any awards or widely known companies that you've helped or a noteworthy statistic regarding your services. Importantly make sure to keep it short and sweet."}, {"key": "why_choose_you", "label": "Why should potential client's choose you over anyone else?", "type": "textarea", "required": true, "section": "Business Development", "help": "Focus on unique benefits you offer and how this helps you solve their problems better than your competitors"}, {"key": "client_problems", "label": "What are the 2-3 main problems that your clients face with hiring internally? Separately, what are the 2-3 main problems that your clients face when working with recruitment agencies?", "type": "textarea", "required": true, "section": "Business Development", "help": "List the top hiring problems your ideal clients are actively dealing with. These should be specific hiring challenges that are on their mind frequently, not general business issues. e.g. Can’t find qualified candidates, Low response rates from good candidates, Low quality candidates from etc"}, {"key": "problem_impact", "label": "How do these problems impact them in their world?", "type": "textarea", "required": true, "section": "Business Development", "help": "Describe how these problems affect your clients day-to-day. Focus on the knock-on effects to time, revenue, delivery, or workload. e.g. Projects are delayed, Senior staff are stretched thin, Revenue targets are being missed"}, {"key": "problem_consequences", "label": "What happens if these problems continue without being solved?", "type": "textarea", "required": true, "section": "Business Development", "help": "Explain the longer-term consequences if the hiring issues continue. Think about risk, growth, and opportunity cost. e.g. Investor's get frustrated, Good candidates go to competitors, Growth plans stall or fail, Key team members begin to leave due to mounting pressure as a result of being under resourced"}, {"key": "fees", "label": "What are your fee's?", "type": "textarea", "required": true, "section": "Business Development", "help": "Please let us know in as much detail as possible your pricing structure based on the recruitment service you provide. On perm we want to know contingent fee's and retainer fee's as a percentage. On temp we want to know hourly rates"}, {"key": "guarantees", "label": "Do you offer any guarantee’s or rebates?", "type": "textarea", "required": true, "section": "Business Development", "help": "If yes, please explain in detail"}, {"key": "case_studies", "label": "What are some of your most noteable case studies and what positive results did you achieve?", "type": "textarea", "required": true, "section": "Business Development", "help": "This is for when prospects ask about who you have worked with/ what you've done in the past"}, {"key": "always_look_candidates", "label": "Which type of candidate are your clients ALWAYS willing to take a look at (even when not hiring immediately)?", "type": "textarea", "required": true, "section": "Business Development", "help": "These should be candidates you can place."}, {"key": "pr_events", "label": "Has your company recently had any good PR or noteworthy presence at industry relevant events?", "type": "textarea", "required": true, "section": "Business Development", "help": "If yes, please explain as much as possible"}, {"key": "notable_clients", "label": "Who are some clients that you've worked with that are well known in the industry?", "type": "textarea", "required": true, "section": "Business Development", "help": "These should be notable companies that your prospects will recognise from their sector and understand your calibre of clients, this will give a higher level of perceived credibility. Please don't list any companies that you have NDA's in place with."}, {"key": "misunderstood_roles", "label": "List some roles that you'd recruit for which are commonly misunderstood by generalist recruiters, and what types of candidates do they typically submit as a result?", "type": "textarea", "required": true, "section": "Business Development", "help": "e.g. For a recruiter specialising in town planning, the role 'Transport Planner with development planning experience' is commonly misunderstood. Generalist recruiters often submit Town Planners, Transport Modellers or Highways Engineers because the job titles sound related - but they're actually distinct specialisms with different skill sets and career paths."}, {"key": "meetings_per_consultant", "label": "On average, how many new client sales meetings are each of your consultants sitting per month?", "type": "textarea", "required": true, "section": "Goals", "help": "If you don't have 180/360 consultants underneath you yet then please let us know how many new sales meetings you are sitting per month on average"}, {"key": "consultant_first_year_revenue", "label": "When bringing on a new consultant, how much revenue do you expect them to generate in their first year?", "type": "textarea", "required": true, "section": "Goals", "help": "We want to know the minimum standard, typically this figure is between 50k-80k. We ask for this to understand your in-house standards so that we can ensure the value we bring exceeds expectations"}, {"key": "client_12m_value", "label": "On average, what is a new client worth to you over a 12 month period?", "type": "text", "required": false, "section": "Goals"}, {"key": "first_30_day_wins", "label": "What win/ wins would you like to see in the first 30 days of the campaign?", "type": "textarea", "required": true, "section": "Goals", "help": "Even though the initial campaign is 90 days we know you're judging us based off of the first 30 days."}, {"key": "success_definition", "label": "What does success look like to you? In other words - what result would you like us to achieve in order for you to renew with us at the end of your trial campaign?", "type": "textarea", "required": true, "section": "Goals", "help": "We would love this to be a long term relationship, so how can we ensure this from our end?"}], "sections": ["Business Details", "Ideal Customer Profile (ICP)", "Business Development", "Goals"]}$j$::jsonb, 1, true);
  INSERT INTO public.client_flow_stages (stage_key, title, subtitle, sort_order, enabled)
  VALUES ('workspace', 'Your team@ mailbox', 'So replies land with you', 30, true) RETURNING id INTO v_stage;
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'google_workspace', 'Set up your team@ mailbox', 'We send campaign email from an address on your own domain so that every reply lands with you and looks like it came from your team. Please create a mailbox called team@ followed by your domain (for example team@abcrecruitment.com) in your Google Workspace, then paste the address here. I''ll collect secure access on our call, never through a form.', 'form', $j${"questions": [{"key": "team_mailbox", "label": "The address you created", "type": "email", "required": true, "help": "e.g. team@abcrecruitment.com", "section": "Mailbox"}], "sections": ["Mailbox"], "inline": true}$j$::jsonb, 1, true);
  INSERT INTO public.client_flow_stages (stage_key, title, subtitle, sort_order, enabled)
  VALUES ('book_call', 'Your onboarding call', 'Sixty minutes with Daniel', 40, true) RETURNING id INTO v_stage;
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'book_onboarding_call', 'Book your onboarding call', 'Let''s get an hour in the diary. Pick any slot that suits you; you''ll see my live availability, UK time, and the invite lands in your inbox with a Meet link the moment you confirm.', 'booking', $j${"event_slug": "onboarding-call-msp-a7w3k"}$j$::jsonb, 1, true);
  INSERT INTO public.client_flow_stages (stage_key, title, subtitle, sort_order, enabled)
  VALUES ('calendar', 'Connect your calendar', 'Meetings straight into your diary', 50, true) RETURNING id INTO v_stage;
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'connect_calendar', 'Connect your calendar to Vexon OS', 'Every meeting we book for you should appear in your diary automatically, with the prospect invited and a video link attached. Connect Google or Microsoft here. A window opens, you approve access, and you''re done.', 'calendar_connect', $j${}$j$::jsonb, 1, true);
  INSERT INTO public.client_flow_stages (stage_key, title, subtitle, sort_order, enabled)
  VALUES ('prepare', 'Get us ready to win', 'A few things that make the first weeks count', 60, true) RETURNING id INTO v_stage;
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'pitch_deck', 'Your pitch deck', 'Do you have a pitch deck or a sales one-pager? If you do, drop it here so the team pitches you the way you pitch yourself. If not, no problem at all; I''ve linked a short guide to putting one together and we can talk it through on our call.', 'yes_no', $j${"question": "Do you have a pitch deck or sales one-pager?", "on_yes": "upload", "accept": ".pdf,.ppt,.pptx,.key,.doc,.docx", "multiple": true, "no_label": "Not yet", "no_guide_label": "How to build a simple pitch deck"}$j$::jsonb, 1, true);
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'target_companies', 'Companies you would like us to prioritise', 'Are there specific companies or warm prospects you''d like us to go after first? A list, even a rough one, lets us target your best-fit accounts from day one rather than working purely from our own research.', 'yes_no', $j${"question": "Do you have a list of companies or warm prospects you would like us to prioritise?", "on_yes": "upload_or_list", "accept": ".csv,.xlsx,.xls,.pdf,.doc,.docx", "multiple": true, "placeholder": "Company name, contact, why they are warm", "min_items": 1}$j$::jsonb, 2, true);
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'reengage', 'Relationships worth re-engaging', 'Some of the quickest wins we see come from companies that already know you: past clients you haven''t worked with for a while, opportunities that went quiet, conversations that never quite converted. Share them and we''ll pick those up in the first week.', 'yes_no', $j${"question": "Are there past clients, dormant opportunities or previous conversations we should re-engage on your behalf?", "on_yes": "upload_or_list", "accept": ".csv,.xlsx,.xls,.pdf,.doc,.docx", "multiple": true, "placeholder": "Company name, when you last spoke, context", "min_items": 1}$j$::jsonb, 3, true);
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'do_not_contact', 'Who we must not contact', 'Are there companies or individuals we must never approach? Current clients, partners, anyone under an agreement or a delicate relationship. Tell us now and they will never appear in a campaign list.', 'yes_no', $j${"question": "Are there any companies or individuals we must not contact?", "on_yes": "upload_or_list", "accept": ".csv,.xlsx,.xls,.pdf,.doc,.docx", "multiple": true, "placeholder": "Company or person, and why", "min_items": 1, "no_label": "No, nobody"}$j$::jsonb, 4, true);
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'fee_plans', 'Your fee plans and terms', 'Do you have documented fee structures or service tiers, for example standard, retained and exclusive? Upload them so we describe your terms exactly as you would.', 'yes_no', $j${"question": "Do you have documented fee plans or service tiers?", "on_yes": "upload", "accept": ".pdf,.doc,.docx,.ppt,.pptx,.xlsx", "multiple": true}$j$::jsonb, 5, true);
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'anything_else', 'Anything else that helps us represent you', 'Case studies, testimonials, brand guidelines, live job specs, awards. Anything that helps us sound like you. If nothing comes to mind, just mark this done and we''ll cover it on the call.', 'yes_no', $j${"question": "Is there anything else that would help us represent you well?", "on_yes": "upload", "accept": ".pdf,.doc,.docx,.ppt,.pptx,.xlsx,.csv,.png,.jpg,.jpeg,.zip", "multiple": true, "no_label": "Nothing for now"}$j$::jsonb, 6, true);
  INSERT INTO public.client_flow_steps (stage_id, step_key, label, description, step_type, config, sort_order, enabled)
  VALUES (v_stage, 'best_practice_guide', 'Read the best practice guide for booked meetings', 'A short guide to getting the most out of the meetings we book for you.', 'read_document', $j${}$j$::jsonb, 7, false);
END $$;

-- 3. Daniel's onboarding event: ON, 60 minutes. Availability rules are his
--    own (Mon 11-17, Tue-Thu 9-17, Fri 9-16 London) and are left alone;
--    free/busy already comes from his real calendar.
UPDATE public.booking_event_types
SET is_active = true,
    accepting_bookings = true,
    duration_minutes = 60,
    name = 'Onboarding call with Daniel (Meridian Sales Partners)',
    description = 'Your 60-minute onboarding call with Daniel, your Customer Success Manager. We walk through your answers, agree the target list and set the campaign up to win early.',
    updated_at = now()
WHERE slug = 'onboarding-call-msp-a7w3k';

-- 4. Upload size cap (25 MB). Types stay open — the per-step accept list is
--    enforced in the browser and the CSM reviews every file.
UPDATE storage.buckets SET file_size_limit = 26214400 WHERE id = 'client-onboarding-assets';
